import numpy as np, time
# How expensive is just reading the matrix in numba vs numpy
from numba import njit

@njit
def colmin_sum(C):
    n = C.shape[0]
    s = 0.0
    for j in range(n):
        mv = C[0, j]
        for i in range(1, n):
            val = C[i, j]
            if val < mv:
                mv = val
        s += mv
    return s

@njit
def rowmin_sum(C):
    n = C.shape[0]
    s = 0.0
    for i in range(n):
        ci = C[i]
        mv = ci[0]
        for j in range(1, n):
            val = ci[j]
            if val < mv:
                mv = val
        s += mv
    return s

