// Fast Jonker-Volgenant assignment for dense double cost matrices.
// Build: c++ -O3 -ffast-math -std=c++17 -shared -fPIC -o lapjv.so lapjv.cpp
#include <cstdint>
#include <cstring>
#include <vector>
#include <algorithm>
#include <limits>
#include <Python.h>

static inline int64_t lapjv(const double* C, int n, int64_t* y_out) {
    const double BIG = 1e100;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> y(n, -1), x(n, -1);
    std::vector<int> free_rows(n);
    int nf = 0;

    // Column reduction, right to left
    for (int j = n - 1; j >= 0; --j) {
        double mv = C[0 * n + j];
        int mi = 0;
        for (int i = 1; i < n; ++i) {
            double val = C[i * n + j];
            if (val < mv) { mv = val; mi = i; }
        }
        v[j] = mv;
        if (y[mi] < 0) { y[mi] = j; x[j] = mi; }
    }

    // Reduction transfer
    for (int i = 0; i < n; ++i) {
        int j = y[i];
        if (j < 0) { free_rows[nf++] = i; continue; }
        const double* ci = C + i * n;
        double min1 = ci[j] - v[j];
        double min2 = BIG;
        for (int k = 0; k < n; ++k) {
            if (k == j) continue;
            double red = ci[k] - v[k];
            if (red < min1) { min2 = min1; min1 = red; }
            else if (red < min2) { min2 = red; }
        }
        u[i] = min1;
        if (min1 < min2) v[j] -= (min2 - min1);
    }

    // Augmenting row reduction, 2 passes
    for (int pass = 0; pass < 2; ++pass) {
        if (nf == 0) break;
        int cnt = nf;
        std::vector<int> cur(free_rows.begin(), free_rows.begin() + cnt);
        nf = 0;
        for (int t = 0; t < cnt; ++t) {
            int i = cur[t];
            const double* ci = C + i * n;
            double umin = ci[0] - v[0];
            double usub = BIG;
            int jmin = 0;
            for (int j = 1; j < n; ++j) {
                double red = ci[j] - v[j];
                if (red < umin) { usub = umin; umin = red; jmin = j; }
                else if (red < usub) { usub = red; }
            }
            u[i] = umin;
            if (umin < usub) v[jmin] -= (usub - umin);
            int prev = x[jmin];
            if (prev >= 0) { y[prev] = -1; free_rows[nf++] = prev; }
            y[i] = jmin;
            x[jmin] = i;
        }
    }

    // Shortest augmenting paths
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n);

    for (int t = 0; t < nf; ++t) {
        int fr = free_rows[t];
        const double* cfr = C + fr * n;
        double ufr = u[fr];
        for (int j = 0; j < n; ++j) {
            dist[j] = cfr[j] - v[j] - ufr;
            pred[j] = fr;
            scanned[j] = 0;
        }
        double mind = BIG;
        int jmin = 0;
        for (int j = 0; j < n; ++j) if (dist[j] < mind) { mind = dist[j]; jmin = j; }

        while (true) {
            scanned[jmin] = 1;
            int im = x[jmin];
            if (im < 0) {
                for (int j = 0; j < n; ++j) {
                    if (scanned[j]) {
                        double delta = dist[j] - mind;
                        v[j] += delta;
                        int im2 = x[j];
                        if (im2 >= 0) u[im2] -= delta;
                    }
                }
                u[fr] = ufr + mind;
                int jc = jmin;
                while (true) {
                    int i = pred[jc];
                    int pj = y[i];
                    y[i] = jc;
                    x[jc] = i;
                    if (i == fr) break;
                    jc = pj;
                }
                break;
            }
            const double* ci = C + im * n;
            double base = ci[jmin] - v[jmin];
            double dbase = dist[jmin];
            double new_mind = BIG;
            int new_j = -1;
            for (int j = 0; j < n; ++j) {
                if (!scanned[j]) {
                    double nd = dbase + ci[j] - v[j] - base;
                    if (nd < dist[j]) { dist[j] = nd; pred[j] = im; }
                    else nd = dist[j];
                    if (nd < new_mind) { new_mind = nd; new_j = j; }
                }
            }
            mind = new_mind;
            jmin = new_j;
        }
    }

    for (int i = 0; i < n; ++i) y_out[i] = y[i];
    return 0;
}

static PyObject* py_lapjv(PyObject* self, PyObject* args) {
    PyObject* buf_obj;
    if (!PyArg_ParseTuple(args, "O", &buf_obj)) return NULL;
    Py_buffer view;
    if (PyObject_GetBuffer(buf_obj, &view, PyBUF_ND | PyBUF_FORMAT) != 0) return NULL;
    if (view.ndim != 2 || view.shape[0] != view.shape[1]) {
        PyBuffer_Release(&view);
        PyErr_SetString(PyExc_ValueError, "expected square 2D array");
        return NULL;
    }
    int n = (int)view.shape[0];
    // Require C-contiguous float64
    if (strcmp(view.format, "d") != 0 || !PyBuffer_IsContiguous(&view, 'C')) {
        PyBuffer_Release(&view);
        PyErr_SetString(PyExc_ValueError, "expected C-contiguous float64");
        return NULL;
    }
    const double* C = (const double*)view.buf;
    PyObject* out = PyList_New(n);
    // use a raw buffer
    std::vector<int64_t> y(n);
    lapjv(C, n, y.data());
    for (int i = 0; i < n; ++i) {
        PyList_SET_ITEM(out, i, PyLong_FromLongLong(y[i]));
    }
    PyBuffer_Release(&view);
    return out;
}

static PyMethodDef methods[] = {
    {"lapjv", py_lapjv, METH_VARARGS, "JV assignment"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "lapjv", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_lapjv(void) { return PyModule_Create(&moduledef); }
