// Optimized Jonker-Volgenant dense assignment.
#include <cstdint>
#include <cstring>
#include <vector>
#include <Python.h>

static void lapjv(const double* __restrict C, int n, int64_t* y_out) {
    const double BIG = 1e100;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> y(n, -1), x(n, -1);
    std::vector<int> free_rows(n);
    int nf = 0;

    // Column reduction, right to left. Cache-unfriendly but done once.
    for (int j = n - 1; j >= 0; --j) {
        double mv = C[j];
        int mi = 0;
        for (int i = 1; i < n; ++i) {
            double val = C[i * n + j];
            if (val < mv) { mv = val; mi = i; }
        }
        v[j] = mv;
        if (y[mi] < 0) { y[mi] = j; x[j] = mi; }
    }

    // Reduction transfer
    for (int i = 0; i < n; ++i) {
        int j = y[i];
        if (j < 0) { free_rows[nf++] = i; continue; }
        const double* ci = C + (size_t)i * n;
        double min1 = ci[j] - v[j];
        double min2 = BIG;
        for (int k = 0; k < n; ++k) {
            double red = ci[k] - v[k];
            // branchless-ish: track two smallest, skipping assigned by using a sentinel compare
            if (k == j) continue;
            if (red < min1) { min2 = min1; min1 = red; }
            else if (red < min2) { min2 = red; }
        }
        u[i] = min1;
        if (min1 < min2) v[j] -= (min2 - min1);
    }

    // Augmenting row reduction
    for (int pass = 0; pass < 2 && nf; ++pass) {
        int cnt = nf;
        std::vector<int> cur(free_rows.begin(), free_rows.begin() + cnt);
        nf = 0;
        for (int t = 0; t < cnt; ++t) {
            int i = cur[t];
            const double* ci = C + (size_t)i * n;
            double umin = BIG, usub = BIG;
            int jmin = 0;
            for (int j = 0; j < n; ++j) {
                double red = ci[j] - v[j];
                if (red < umin) { usub = umin; umin = red; jmin = j; }
                else if (red < usub) { usub = red; }
            }
            u[i] = umin;
            if (umin < usub) v[jmin] -= (usub - umin);
            int prev = x[jmin];
            if (prev >= 0) { y[prev] = -1; free_rows[nf++] = prev; }
            y[i] = jmin;
            x[jmin] = i;
        }
    }

    // Shortest augmenting paths with a ready-set of improving columns
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n);
    std::vector<int> ready(n);

    for (int t = 0; t < nf; ++t) {
        int fr = free_rows[t];
        const double* cfr = C + (size_t)fr * n;
        double ufr = u[fr];

        double mind = BIG;
        int jmin = 0;
        int nready = 0;
        for (int j = 0; j < n; ++j) {
            double d = cfr[j] - v[j] - ufr;
            dist[j] = d;
            pred[j] = fr;
            scanned[j] = 0;
            if (d < mind) { mind = d; jmin = j; }
        }

        while (true) {
            scanned[jmin] = 1;
            int im = x[jmin];
            if (im < 0) {
                for (int j = 0; j < n; ++j) {
                    if (scanned[j]) {
                        double delta = dist[j] - mind;
                        v[j] += delta;
                        int im2 = x[j];
                        if (im2 >= 0) u[im2] -= delta;
                    }
                }
                u[fr] = ufr + mind;
                int jc = jmin;
                while (true) {
                    int i = pred[jc];
                    int pj = y[i];
                    y[i] = jc;
                    x[jc] = i;
                    if (i == fr) break;
                    jc = pj;
                }
                break;
            }
            const double* ci = C + (size_t)im * n;
            double base = ci[jmin] - v[jmin];
            double dbase = dist[jmin];
            double new_mind = BIG;
            int new_j = -1;
            // scan all unscanned; track new min in the same pass
            for (int j = 0; j < n; ++j) {
                if (scanned[j]) continue;
                double nd = dbase + ci[j] - v[j] - base;
                double dj = dist[j];
                if (nd < dj) { dist[j] = nd; pred[j] = im; dj = nd; }
                if (dj < new_mind) { new_mind = dj; new_j = j; }
            }
            mind = new_mind;
            jmin = new_j;
        }
    }

    for (int i = 0; i < n; ++i) y_out[i] = y[i];
}

static PyObject* py_lapjv(PyObject* self, PyObject* args) {
    PyObject* buf_obj;
    if (!PyArg_ParseTuple(args, "O", &buf_obj)) return NULL;
    Py_buffer view;
    if (PyObject_GetBuffer(buf_obj, &view, PyBUF_ND | PyBUF_FORMAT) != 0) return NULL;
    if (view.ndim != 2 || view.shape[0] != view.shape[1] ||
        strcmp(view.format, "d") != 0 || !PyBuffer_IsContiguous(&view, 'C')) {
        PyBuffer_Release(&view);
        PyErr_SetString(PyExc_ValueError, "expected square C-contiguous float64");
        return NULL;
    }
    int n = (int)view.shape[0];
    // Return numpy array via buffer protocol? Build a bytes object and let caller wrap.
    // Faster: write into a preallocated array passed as second arg. For now return memoryview of a new bytes.
    PyObject* out = PyBytes_FromStringAndSize(NULL, n * (Py_ssize_t)sizeof(int64_t));
    if (!out) { PyBuffer_Release(&view); return NULL; }
    int64_t* y = (int64_t*)PyBytes_AS_STRING(out);
    lapjv((const double*)view.buf, n, y);
    PyBuffer_Release(&view);
    return out;
}

static PyMethodDef methods[] = {
    {"lapjv", py_lapjv, METH_VARARGS, "JV assignment, returns bytes of int64 col indices"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "lapjv", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_lapjv(void) { return PyModule_Create(&moduledef); }
