// Jonker-Volgenant with candidate finding (improved SAP initialization).
#include <cstdint>
#include <cstring>
#include <vector>
#include <Python.h>

static void lapjv(const double* C, int n, int64_t* y_out) {
    const double BIG = 1e100;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> y(n, -1), x(n, -1);          // y[row]=col, x[col]=row
    std::vector<int> free_rows(n);
    std::vector<int> unique(n, 0);                 // columns that are unique minima
    int nf = 0;

    // ---- COLUMN REDUCTION (right to left) ----
    for (int j = n - 1; j >= 0; --j) {
        double mv = C[j];
        int mi = 0;
        for (int i = 1; i < n; ++i) {
            double val = C[(size_t)i * n + j];
            if (val < mv) { mv = val; mi = i; }
        }
        v[j] = mv;
        if (y[mi] < 0) {
            y[mi] = j; x[j] = mi; unique[j] = 1;
        } else {
            unique[j] = 0;
        }
    }

    // ---- REDUCTION TRANSFER ----
    for (int i = 0; i < n; ++i) {
        int j = y[i];
        if (j < 0) { free_rows[nf++] = i; continue; }
        const double* ci = C + (size_t)i * n;
        double min1 = BIG, min2 = BIG;
        int jmin = -1;
        for (int k = 0; k < n; ++k) {
            double red = ci[k] - v[k];
            if (red < min1) { min2 = min1; min1 = red; jmin = k; }
