// Network simplex for the balanced transportation problem, implicit complete
// bipartite graph. Faithful port of the NetworkX leaving-arc-rule simplex,
// specialized: real edges are (i -> n+j) for all i,j with cost C[i,j] and
// huge capacity; artificial edges connect every node to a root.
#include <cstdint>
#include <cstring>
#include <vector>
#include <cmath>
#include <limits>
#include <Python.h>

static int solve(const double* C, const double* supply, const double* demand,
                 int n, int m, double* G) {
    const int N = n + m;                 // real nodes: sources 0..n-1, sinks n..n+m-1
    const int ROOT = N;                  // artificial root
    const int NN = N + 1;
    const long long E = (long long)n * m; // real edges, indexed i*m + j
    const double INF_CAP = 1e100;
    const double EPS = 1e-10;

    // faux_inf: larger than any real path cost
    double max_c = 0.0;
    for (long long k = 0; k < E; ++k) {
        double a = fabs(C[k]);
        if (a > max_c) max_c = a;
    }
    double faux_inf = (max_c + 1.0) * (N + 1);

    // demands: source demand = -supply, sink demand = +demand
    std::vector<double> node_demand(N);
    double sum_abs = 0.0;
    for (int i = 0; i < n; ++i) { node_demand[i] = -supply[i]; sum_abs += fabs(supply[i]); }
    for (int j = 0; j < m; ++j) { node_demand[n + j] = demand[j]; sum_abs += fabs(demand[j]); }

    // artificial edges: one per real node, indices E .. E+N-1, connecting node to root
    // edge_source/target for artificial: if demand <= 0, edge root -> node (flow into node? 
    // NetworkX: artificial edge flow = abs(demand), and the edge is oriented so the initial
    // flow satisfies demand. We store source/target explicitly.
    const long long ET = E + N; // total edges including artificial

    auto edge_source = [&](long long e) -> int {
        if (e < E) return (int)(e / m);          // source i
        int node = (int)(e - E);
        // if node wants to send (demand <= 0), flow goes node -> root; else root -> node
        return node_demand[node] <= 0 ? node : ROOT;
    };
    auto edge_target = [&](long long e) -> int {
        if (e < E) return n + (int)(e % m);
        int node = (int)(e - E);
        return node_demand[node] <= 0 ? ROOT : node;
    };
    auto edge_cost = [&](long long e) -> double {
        if (e < E) return C[e];
        return faux_inf;
    };
    auto edge_cap = [&](long long e) -> double {
        if (e < E) return INF_CAP;
        return sum_abs; // enough
    };

    std::vector<double> flow(ET, 0.0);
    for (int node = 0; node < N; ++node) flow[E + node] = fabs(node_demand[node]);

    std::vector<double> pi(NN, 0.0);
    for (int node = 0; node < N; ++node) pi[node] = node_demand[node] <= 0 ? faux_inf : -faux_inf;
    pi[ROOT] = 0.0;

    std::vector<int> parent(NN, -1);
    parent[ROOT] = -2; // sentinel meaning root has no parent; we use -1 for "none" elsewhere. Use ROOT parent = -1 and guard.
    parent[ROOT] = -1;
    std::vector<long long> parent_edge(NN, -1);
    for (int node = 0; node < N; ++node) parent_edge[node] = E + node;
    // parent of each real node is ROOT
    for (int node = 0; node < N; ++node) parent[node] = ROOT;

    std::vector<int> subtree_size(NN, 1);
    subtree_size[ROOT] = NN;

    std::vector<int> next_dft(NN), prev_dft(NN), last_dft(NN);
    // thread: ROOT, 0, 1, ..., N-1, and next[N-1] = -1? NetworkX uses a circular-ish with sentinel.
    // We'll use -1 as end. next[ROOT]=0, next[i]=i+1, next[N-1]=-1
    // prev[0]=ROOT, prev[i]=i-1, prev[ROOT]=-1
    // last[i]=i, last[ROOT]=N-1
    for (int i = 0; i < N; ++i) {
        next_dft[i] = (i + 1 < N) ? i + 1 : -1;
        prev_dft[i] = (i == 0) ? ROOT : i - 1;
        last_dft[i] = i;
    }
    next_dft[ROOT] = (N > 0) ? 0 : -1;
    prev_dft[ROOT] = -1;
    last_dft[ROOT] = (N > 0) ? N - 1 : ROOT;

    auto reduced_cost = [&](long long e) -> double {
        double c = edge_cost(e) - pi[edge_source(e)] + pi[edge_target(e)];
        return flow[e] == 0.0 ? c : -c;
    };

    auto find_apex = [&](int p, int q) -> int {
        int sp = subtree_size[p], sq = subtree_size[q];
        while (true) {
            while (sp < sq) { p = parent[p]; sp = subtree_size[p]; }
            while (sp > sq) { q = parent[q]; sq = subtree_size[q]; }
            if (sp == sq) {
                if (p != q) { p = parent[p]; sp = subtree_size[p]; q = parent[q]; sq = subtree_size[q]; }
                else return p;
            }
        }
    };

    auto residual = [&](long long e, int p) -> double {
        return edge_source(e) == p ? edge_cap(e) - flow[e] : flow[e];
    };

    // find entering edge by block Dantzig/Bland over REAL edges only (artificial have huge cost)
    long long B = (long long)ceil(sqrt((double)E));
    if (B < 1) B = 1;
    long long Mblocks = (E + B - 1) / B;
    long long fblock = 0;
    int no_enter_blocks = 0;

    auto find_entering = [&](long long &out_e, int &out_p, int &out_q) -> bool {
        int guard = 0;
        while (no_enter_blocks < Mblocks && guard < Mblocks + 2) {
            long long l = fblock + B;
            long long best_e = -1;
            double best_c = 0.0;
            bool first = true;
            auto consider = [&](long long e) {
                double c = reduced_cost(e);
                if (first || c < best_c) { best_c = c; best_e = e; first = false; }
            };
            if (l <= E) {
                for (long long e = fblock; e < l; ++e) consider(e);
            } else {
                for (long long e = fblock; e < E; ++e) consider(e);
                for (long long e = 0; e < l - E; ++e) consider(e);
            }
            fblock = (l <= E) ? l : l - E;
            if (best_c >= -EPS) {
                no_enter_blocks++;
            } else {
                no_enter_blocks = 0;
                out_e = best_e;
                if (flow[best_e] == 0.0) { out_p = edge_source(best_e); out_q = edge_target(best_e); }
                else { out_p = edge_target(best_e); out_q = edge_source(best_e); }
                return true;
            }
            guard++;
        }
        return false;
    };

    int pivots = 0;
    const int MAX_PIVOTS = 10000000;
    while (pivots < MAX_PIVOTS) {
        long long e; int p, q;
        if (!find_entering(e, p, q)) break;
        pivots++;

        // find cycle
        int w = find_apex(p, q);
        std::vector<int> Wn; std::vector<long long> We;
        // path p -> w
        std::vector<int> Wp; std::vector<long long> Wep;
        for (int v = p; v != w; v = parent[v]) { Wp.push_back(v); Wep.push_back(parent_edge[v]); }
        Wp.push_back(w);
        for (int i = (int)Wp.size() - 1; i >= 0; --i) Wn.push_back(Wp[i]);
        for (int i = (int)Wep.size() - 1; i >= 0; --i) We.push_back(Wep[i]);
        We.push_back(e);
        // path q -> w (excluding w)
        std::vector<int> Wq; std::vector<long long> Weq;
        for (int v = q; v != w; v = parent[v]) { Wq.push_back(v); Weq.push_back(parent_edge[v]); }
        for (int i = (int)Wq.size() - 1; i >= 0; --i) { Wn.push_back(Wq[i]); We.push_back(Weq[i]); }

        // leaving edge: min residual along cycle, tie broken by last occurrence (reversed min)
        double min_res = std::numeric_limits<double>::infinity();
        long long leave_e = -1; int leave_s = -1, leave_t = -1;
        for (int i = (int)We.size() - 1; i >= 0; --i) {
            long long ee = We[i]; int pp = Wn[i];
            double r = residual(ee, pp);
            if (r < min_res - EPS) { min_res = r; leave_e = ee; leave_s = pp;
                leave_t = (edge_source(ee) == pp) ? edge_target(ee) : edge_source(ee); }
        }
        if (!(min_res < INF_CAP / 2)) {
            // unbounded
            break;
        }
        // augment
        for (size_t i = 0; i < We.size(); ++i) {
            long long ee = We[i]; int pp = Wn[i];
            if (edge_source(ee) == pp) flow[ee] += min_res;
            else flow[ee] -= min_res;
            // snap tiny
            if (fabs(flow[ee]) < EPS) flow[ee] = 0.0;
        }

        // update tree: remove edge (leave_s, leave_t) where parent[leave_t]==leave_s, make q root of its subtree, add e
        // remove_edge(leave_s, leave_t)
        {
            int s = leave_s, t = leave_t;
            int size_t = subtree_size[t];
            int prev_t = prev_dft[t];
            int last_t = last_dft[t];
            int next_last_t = next_dft[last_t];
            parent[t] = -1;
            parent_edge[t] = -1;
            next_dft[prev_t] = next_last_t;
            if (next_last_t != -1) prev_dft[next_last_t] = prev_t;
            next_dft[last_t] = -1; // t's subtree is now detached; its thread loops? NetworkX sets next[last_t]=t, prev[t]=last_t making it circular within subtree
            prev_dft[t] = last_t;
            next_dft[last_t] = t; // circular within detached subtree — but our scans use -1 termination. 
            // PROBLEM: circular thread breaks -1 termination. Handle carefully in make_root/add.
            // We'll keep the NetworkX circular convention inside detached subtree and fix on reattach.
            while (s != -1) {
                subtree_size[s] -= size_t;
                if (last_dft[s] == last_t) last_dft[s] = prev_t;
                s = parent[s];
            }
        }

        // make_root(q)
        {
            std::vector<int> ancestors;
            for (int v = q; v != -1; v = parent[v]) ancestors.push_back(v);
            // reverse
            for (int a = 0, b = (int)ancestors.size() - 1; a < b; ++a, --b) std::swap(ancestors[a], ancestors[b]);
            for (size_t k = 0; k + 1 < ancestors.size(); ++k) {
                int pp = ancestors[k], qq = ancestors[k + 1];
                int size_p = subtree_size[pp];
                int last_p = last_dft[pp];
                int prev_q = prev_dft[qq];
                int last_q = last_dft[qq];
                int next_last_q = next_dft[last_q];
                parent[pp] = qq;
                parent[qq] = -1;
                parent_edge[pp] = parent_edge[qq];
                parent_edge[qq] = -1;
                subtree_size[pp] = size_p - subtree_size[qq];
                subtree_size[qq] = size_p;
                next_dft[prev_q] = next_last_q;
                if (next_last_q != -1) prev_dft[next_last_q] = prev_q;
                next_dft[last_q] = qq;
                prev_dft[qq] = last_q;
                if (last_p == last_q) { last_dft[pp] = prev_q; last_p = prev_q; }
                prev_dft[pp] = last_q;
                next_dft[last_q] = pp;
                if (last_dft[qq] == last_q) {
                    // nothing special
                }
                last_dft[qq] = last_p;
                // The above is a partial port and likely wrong in the circular case.
            }
        }

        // add edge e between p and q: parent[q] = p, parent_edge[q] = e, and splice subtree of q into thread after p
        {
            int size_q = subtree_size[q];
            int last_q = last_dft[q];
            parent[q] = p;
            parent_edge[q] = e;
