            }
            f = l;
            if (best_c >= -EPS) { no_enter++; }
            else {
                no_enter = 0;
                i = best;
                if (flow[i] == 0.0) { p = edge_source(i); q = edge_target(i); }
                else { p = edge_target(i); q = edge_source(i); }
