        }
        return false;
    }

    int run(double* G) {
        long long B = (long long)ceil(sqrt((double)E));
        if (B < 1) B = 1;
        long long M = (E + B - 1) / B;
        long long f = 0; int no_enter = 0;
        int pivots = 0;
