                    t = edge_source(j) == s ? edge_target(j) : edge_source(j); }
            }
            augment(Wn, We, min_res);
            pivots++;
            if (i != j) {
                if (parent[idx(t)] != s) { int tmp = s; s = t; t = tmp; }
                // We.index(i) > We.index(j)?
                int pos_i = -1, pos_j = -1;
                for (int k = 0; k < (int)We.size(); ++k) {
                    if (We[k] == i && pos_i < 0) pos_i = k;
                    if (We[k] == j && pos_j < 0) pos_j = k;
                }
                if (pos_i > pos_j) { int tmp = p; p = q; q = tmp; }
                remove_edge(s, t);
                make_root(q);
                add_edge(i, p, q);
                update_potentials(i, p, q);
            }
            if (pivots > 5000000) break;
        }
        std::memset(G, 0, sizeof(double) * (size_t)n * m);
        for (long long e = 0; e < E; ++e) if (flow[e] != 0.0) G[e] = flow[e];
        return pivots;
    }
};

static PyObject* py_solve(PyObject* self, PyObject* args) {
    PyObject *a_obj, *b_obj, *M_obj, *G_obj;
    if (!PyArg_ParseTuple(args, "OOOO", &a_obj, &b_obj, &M_obj, &G_obj)) return NULL;
    Py_buffer a, b, M, G;
    if (PyObject_GetBuffer(a_obj, &a, PyBUF_ND) || PyObject_GetBuffer(b_obj, &b, PyBUF_ND) ||
        PyObject_GetBuffer(M_obj, &M, PyBUF_ND) || PyObject_GetBuffer(G_obj, &G, PyBUF_WRITABLE | PyBUF_ND))
        return NULL;
    int n = (int)a.shape[0], m = (int)b.shape[0];
    Solver S;
    S.n = n; S.m = m; S.N = n + m; S.root = n + m; S.E = (long long)n * m;
    S.C = (const double*)M.buf;
    S.demand.resize(S.N);
    double sum_abs_w = 0, sum_abs_d = 0, sum_cap = 0;
    for (int i = 0; i < n; ++i) { S.demand[i] = -((const double*)a.buf)[i]; sum_abs_d += fabs(S.demand[i]); }
    for (int j = 0; j < m; ++j) { S.demand[n + j] = ((const double*)b.buf)[j]; sum_abs_d += fabs(S.demand[n + j]); }
    for (long long e = 0; e < S.E; ++e) sum_abs_w += fabs(S.C[e]);
    sum_cap = (double)S.E * 0; // capacities are inf, NetworkX sums only finite caps -> 0
    double mx = std::max(sum_cap, std::max(sum_abs_w, sum_abs_d));
    S.faux_inf = 3.0 * (mx > 0 ? mx : 1.0);

    S.flow.assign(S.E + S.N, 0.0);
    for (int node = 0; node < S.N; ++node) S.flow[S.E + node] = fabs(S.demand[node]);
    S.pi.assign(S.N + 1, 0.0);
    for (int node = 0; node < S.N; ++node) S.pi[node] = S.demand[node] <= 0 ? S.faux_inf : -S.faux_inf;
    S.pi[S.root] = 0.0;
    S.parent.assign(S.N + 1, -1); // parent is root (-1) for all real nodes
    S.parent[S.root] = -2;        // root's parent is None
    S.parent_edge.assign(S.N + 1, -1);
    for (int node = 0; node < S.N; ++node) S.parent_edge[node] = S.E + node;
    S.subtree_size.assign(S.N + 1, 1);
    S.subtree_size[S.root] = S.N + 1;
    S.next_dft.assign(S.N + 1, -1);
    S.prev_dft.assign(S.N + 1, -1);
    S.last_dft.assign(S.N + 1, -1);
    // NetworkX init (nodes 0..n-1, root stored as the extra slot, referenced as -1):
    // next = [1, 2, ..., N-1, -1, 0]  where last entry is root's next
    // prev = [-1, 0, 1, ..., N-2, N-1]  -- wait, list(range(-1, N)) = [-1,0,1,...,N-1]
    //   prev[0] = -1 (root), prev[i] = i-1, and the extra slot prev[root] = N-1
    // last = [0,1,...,N-1, N-1]
    for (int i = 0; i < S.N; ++i) {
        S.next_dft[i] = (i + 1 < S.N) ? i + 1 : -1;
        S.prev_dft[i] = (i == 0) ? -1 : i - 1;
        S.last_dft[i] = i;
    }
    S.next_dft[S.root] = 0;
    S.prev_dft[S.root] = S.N - 1;
    S.last_dft[S.root] = S.N - 1;

    int pivots = S.run((double*)G.buf);
    PyBuffer_Release(&a); PyBuffer_Release(&b); PyBuffer_Release(&M); PyBuffer_Release(&G);
    return PyLong_FromLong(pivots);
}

