// Network simplex for a bipartite transportation problem given as an explicit
// edge list. Faithful port of networkx leaving-arc network simplex.
#include <cstdint>
#include <cstring>
#include <vector>
#include <cmath>
#include <algorithm>
#include <Python.h>

struct Solver {
    int n, m, N, root;
    long long E;
    const int* src;      // length E
    const int* dst;      // length E (sink index 0..m-1)
    const double* cost;  // length E
    double faux_inf;

    std::vector<double> demand;
    std::vector<double> flow;
    std::vector<double> pi;
    std::vector<int> parent;
    std::vector<long long> parent_edge;
    std::vector<int> subtree_size;
    std::vector<int> next_dft, prev_dft, last_dft;

    int idx(int node) const { return node < 0 ? root : node; }

    int edge_source(long long e) const {
        if (e < E) return src[e];
        int node = (int)(e - E);
        return demand[node] > 0 ? -1 : node;
    }
    int edge_target(long long e) const {
        if (e < E) return n + dst[e];
        int node = (int)(e - E);
        return demand[node] > 0 ? node : -1;
    }
    double edge_weight(long long e) const { return e < E ? cost[e] : faux_inf; }

    double reduced_cost(long long e) const {
        int s = edge_source(e), t = edge_target(e);
        double c = edge_weight(e) - pi[idx(s)] + pi[idx(t)];
        return flow[e] == 0.0 ? c : -c;
    }
    double residual(long long e, int p) const {
        return edge_source(e) == p ? faux_inf - flow[e] : flow[e];
    }

    int find_apex(int p, int q) const {
        int sp = subtree_size[idx(p)], sq = subtree_size[idx(q)];
        while (true) {
            while (sp < sq) { p = parent[idx(p)]; sp = subtree_size[idx(p)]; }
            while (sp > sq) { q = parent[idx(q)]; sq = subtree_size[idx(q)]; }
            if (sp == sq) {
                if (p != q) {
                    p = parent[idx(p)]; sp = subtree_size[idx(p)];
                    q = parent[idx(q)]; sq = subtree_size[idx(q)];
                } else return p;
            }
        }
    }

    void trace_path(int p, int w, std::vector<int>& Wn, std::vector<long long>& We) const {
        Wn.clear(); We.clear();
        Wn.push_back(p);
        while (p != w) {
            We.push_back(parent_edge[idx(p)]);
            p = parent[idx(p)];
            Wn.push_back(p);
        }
    }

    void find_cycle(long long i, int p, int q, std::vector<int>& Wn, std::vector<long long>& We) {
        int w = find_apex(p, q);
        std::vector<int> A; std::vector<long long> Ae;
        trace_path(p, w, A, Ae);
        std::reverse(A.begin(), A.end());
        std::reverse(Ae.begin(), Ae.end());
        Wn.swap(A); We.swap(Ae);
        if (!(We.size() == 1 && We[0] == i)) We.push_back(i);
        std::vector<int> B; std::vector<long long> Be;
        trace_path(q, w, B, Be);
        if (!B.empty()) B.pop_back();
        Wn.insert(Wn.end(), B.begin(), B.end());
        We.insert(We.end(), Be.begin(), Be.end());
    }

    void augment(const std::vector<int>& Wn, const std::vector<long long>& We, double f) {
        for (size_t k = 0; k < We.size(); ++k) {
            long long e = We[k];
            if (edge_source(e) == Wn[k]) flow[e] += f;
            else flow[e] -= f;
        }
    }

    void remove_edge(int s, int t) {
        int size_t = subtree_size[idx(t)];
        int prev_t = prev_dft[idx(t)];
        int last_t = last_dft[idx(t)];
        int next_last_t = next_dft[idx(last_t)];
        parent[idx(t)] = -2;
        parent_edge[idx(t)] = -1;
        next_dft[idx(prev_t)] = next_last_t;
        prev_dft[idx(next_last_t)] = prev_t;
        next_dft[idx(last_t)] = t;
        prev_dft[idx(t)] = last_t;
        while (s != -2) {
            subtree_size[idx(s)] -= size_t;
            if (last_dft[idx(s)] == last_t) last_dft[idx(s)] = prev_t;
            s = parent[idx(s)];
        }
    }

    void make_root(int q) {
        std::vector<int> ancestors;
        while (q != -2) { ancestors.push_back(q); q = parent[idx(q)]; }
        std::reverse(ancestors.begin(), ancestors.end());
        for (size_t k = 0; k + 1 < ancestors.size(); ++k) {
            int p = ancestors[k], qq = ancestors[k + 1];
            int size_p = subtree_size[idx(p)];
            int last_p = last_dft[idx(p)];
            int prev_q = prev_dft[idx(qq)];
            int last_q = last_dft[idx(qq)];
            int next_last_q = next_dft[idx(last_q)];
            parent[idx(p)] = qq;
            parent[idx(qq)] = -2;
            parent_edge[idx(p)] = parent_edge[idx(qq)];
            parent_edge[idx(qq)] = -1;
            subtree_size[idx(p)] = size_p - subtree_size[idx(qq)];
            subtree_size[idx(qq)] = size_p;
            next_dft[idx(prev_q)] = next_last_q;
            prev_dft[idx(next_last_q)] = prev_q;
            next_dft[idx(last_q)] = qq;
            prev_dft[idx(qq)] = last_q;
            if (last_p == last_q) { last_dft[idx(p)] = prev_q; last_p = prev_q; }
            prev_dft[idx(p)] = last_q;
            next_dft[idx(last_q)] = p;
            next_dft[idx(last_p)] = qq;
            prev_dft[idx(qq)] = last_p;
            last_dft[idx(qq)] = last_p;
        }
    }

    void add_edge(long long i, int p, int q) {
        int last_p = last_dft[idx(p)];
        int next_last_p = next_dft[idx(last_p)];
        int size_q = subtree_size[idx(q)];
        int last_q = last_dft[idx(q)];
        parent[idx(q)] = p;
        parent_edge[idx(q)] = i;
        next_dft[idx(last_p)] = q;
        prev_dft[idx(q)] = last_p;
        prev_dft[idx(next_last_p)] = last_q;
        next_dft[idx(last_q)] = next_last_p;
        while (p != -2) {
            subtree_size[idx(p)] += size_q;
            if (last_dft[idx(p)] == last_p) last_dft[idx(p)] = last_q;
            p = parent[idx(p)];
        }
    }

    void update_potentials(long long i, int p, int q) {
        double d = (q == edge_target(i))
            ? pi[idx(p)] - edge_weight(i) - pi[idx(q)]
            : pi[idx(p)] + edge_weight(i) - pi[idx(q)];
        int v = q, l = last_dft[idx(q)];
        while (true) {
            pi[idx(v)] += d;
            if (v == l) break;
            v = next_dft[idx(v)];
        }
    }

    // returns number of pivots; writes flow of real edges into flow[0..E)
    int run() {
        long long B = (long long)ceil(sqrt((double)E));
        if (B < 1) B = 1;
        long long Mblk = (E + B - 1) / B;
        long long f = 0; int no_enter = 0;
        int pivots = 0;
        std::vector<int> Wn; std::vector<long long> We;
        const double EPS = 1e-9;
        const int MAX_PIVOTS = 2000000;
        while (pivots < MAX_PIVOTS) {
            // find entering
            long long i = -1; int p = 0, q = 0; bool found = false;
            int guard = 0;
            while (no_enter < Mblk && guard < Mblk + 2) {
                long long l = f + B;
                long long best = -1; double best_c = 0; bool first = true;
                auto consider = [&](long long e) {
                    double c = reduced_cost(e);
                    if (first || c < best_c) { best_c = c; best = e; first = false; }
                };
                if (l <= E) { for (long long e = f; e < l; ++e) consider(e); }
                else {
                    for (long long e = f; e < E; ++e) consider(e);
                    l -= E;
                    for (long long e = 0; e < l; ++e) consider(e);
                }
                f = l;
                if (best_c >= -EPS) no_enter++;
                else {
                    no_enter = 0; i = best;
                    if (flow[i] == 0.0) { p = edge_source(i); q = edge_target(i); }
                    else { p = edge_target(i); q = edge_source(i); }
                    found = true; break;
                }
                guard++;
