            if (!found) break;

            find_cycle(i, p, q, Wn, We);
            double min_res = 1e300; long long j = -1; int s = 0, t = 0;
            for (int k = (int)We.size() - 1; k >= 0; --k) {
                double r = residual(We[k], Wn[k]);
                if (r < min_res) {
                    min_res = r; j = We[k]; s = Wn[k];
                    t = edge_source(j) == s ? edge_target(j) : edge_source(j);
                }
            }
            augment(Wn, We, min_res);
            pivots++;
            if (i != j) {
                if (parent[idx(t)] != s) { int tmp = s; s = t; t = tmp; }
                int pos_i = -1, pos_j = -1;
