};

// solve(src, dst, cost, supply, demand, out_flow) 
// src, dst: int64 arrays length E; dst is sink index 0..m-1
// supply length n, demand length m, out_flow length E (writable float64)
static PyObject* py_solve(PyObject* self, PyObject* args) {
