        int v = q, l = last_dft[idx(q)];
        while (true) { pi[idx(v)] += d; if (v == l) break; v = next_dft[idx(v)]; }
    }

    // one pivot on current edge set; returns false if optimal over current edges
    bool pivot_once(long long& f, int& no_enter, long long B, long long Mblk,
                    std::vector<int>& Wn, std::vector<long long>& We) {
        const double EPS = 1e-9;
        int guard = 0;
        long long i = -1; int p = 0, q = 0; bool found = false;
        while (no_enter < Mblk && guard < Mblk + 2) {
            long long l = f + B;
            long long best = -1; double best_c = 0; bool first = true;
