            for (int k = 0; k < (int)We.size(); ++k) {
                if (pos_i < 0 && We[k] == i) pos_i = k;
                if (pos_j < 0 && We[k] == j) pos_j = k;
            }
            if (pos_i > pos_j) { int tmp = p; p = q; q = tmp; }
            remove_edge(s, t); make_root(q); add_edge(i, p, q); update_potentials(i, p, q);
        }
        return true;
    }

    void optimize() {
        long long B = std::max(1LL, (long long)ceil(sqrt((double)std::max(E, 1LL))));
        long long Mblk = (E + B - 1) / B;
        long long f = 0; int no_enter = 0;
        std::vector<int> Wn; std::vector<long long> We;
        int pivots = 0;
        while (pivots < 5000000 && pivot_once(f, no_enter, B, Mblk, Wn, We)) pivots++;
    }

    // price full matrix; append up to `cap` most-violated edges. returns count added.
    int price_and_add(int cap) {
        // reduced cost rc(i,j) = C[i,j] - pi[i] + pi[n+j]
        // collect violations with a small heap of size cap
        struct Item { double rc; int i, j; };
        std::vector<Item> heap; heap.reserve(cap);
        auto worse = [](const Item& a, const Item& b) { return a.rc > b.rc; }; // min-heap by rc (most negative on top? we want the most negative, so max-heap of the kept least-negative)
        for (int i = 0; i < n; ++i) {
            const double* row = C + (size_t)i * m;
            double ps = pi[i];
            for (int j = 0; j < m; ++j) {
                double rc = row[j] - ps + pi[n + j];
                if (rc < -1e-8) {
                    if ((int)heap.size() < cap) {
                        heap.push_back({rc, i, j});
                        std::push_heap(heap.begin(), heap.end(), [](const Item& a, const Item& b){ return a.rc < b.rc; });
                    } else if (rc < heap.front().rc) {
                        std::pop_heap(heap.begin(), heap.end(), [](const Item& a, const Item& b){ return a.rc < b.rc; });
                        heap.back() = {rc, i, j};
                        std::push_heap(heap.begin(), heap.end(), [](const Item& a, const Item& b){ return a.rc < b.rc; });
                    }
                }
            }
        }
        if (heap.empty()) return 0;
