        else std::fill(present.begin(), present.begin() + n * m, 0);
        for (long long e = 0; e < E; ++e) present[(size_t)src[e] * m + dst[e]] = 1;
        int added = 0;
        long long oldE = E;
        for (auto& it : heap) {
            size_t key = (size_t)it.i * m + it.j;
            if (present[key]) continue;
