    for (int node = 0; node < S.N; ++node) S.flow[S.E + node] = fabs(S.demand[node]);
    S.pi.assign(S.N + 1, 0.0);
    for (int node = 0; node < S.N; ++node) S.pi[node] = S.demand[node] <= 0 ? S.faux_inf : -S.faux_inf;
    S.parent.assign(S.N + 1, -1); S.parent[S.root] = -2;
    S.parent_edge.assign(S.N + 1, -1);
    for (int node = 0; node < S.N; ++node) S.parent_edge[node] = S.E + node;
    S.subtree_size.assign(S.N + 1, 1); S.subtree_size[S.root] = S.N + 1;
    S.next_dft.assign(S.N + 1, -1); S.prev_dft.assign(S.N + 1, -1); S.last_dft.assign(S.N + 1, -1);
