    double* Go = (double*)G.buf;
    std::memset(Go, 0, sizeof(double) * n * m);
    for (long long e = 0; e < S.E; ++e) if (S.flow[e] != 0.0) Go[(size_t)S.src[e] * m + S.dst[e]] = S.flow[e];
    PyBuffer_Release(&a); PyBuffer_Release(&b); PyBuffer_Release(&M); PyBuffer_Release(&G);
    return PyLong_FromLong(rounds);
}

