    // but the argmin itself is the expensive part. Compute all column argmins
    // in parallel first, then assign right-to-left.
    std::vector<int> col_arg(n);
    std::vector<double> col_min(n);
    #pragma omp parallel for schedule(static)
    for (int j = 0; j < n; ++j) {
        double mv = C[j]; int mi = 0;
        for (int i = 1; i < n; ++i) {
            double val = C[(size_t)i * n + j];
            if (val < mv) { mv = val; mi = i; }
        }
        col_min[j] = mv; col_arg[j] = mi;
    }
    for (int j = n - 1; j >= 0; --j) {
        v[j] = col_min[j];
        int mi = col_arg[j];
        if (y[mi] < 0) { y[mi] = j; x[j] = mi; }
    }

    std::vector<int> free_rows(n);
    int nf = 0;
    for (int i = 0; i < n; ++i) {
        int j = y[i];
        if (j < 0) { free_rows[nf++] = i; continue; }
        const double* ci = C + (size_t)i * n;
        double min1 = ci[j] - v[j], min2 = BIG;
        for (int k = 0; k < n; ++k) {
            if (k == j) continue;
            double red = ci[k] - v[k];
            if (red < min1) { min2 = min1; min1 = red; }
            else if (red < min2) min2 = red;
        }
        u[i] = min1;
        if (min1 < min2) v[j] -= (min2 - min1);
    }

    for (int pass = 0; pass < 2 && nf; ++pass) {
        int cnt = nf;
        std::vector<int> cur(free_rows.begin(), free_rows.begin() + cnt);
        nf = 0;
        for (int t = 0; t < cnt; ++t) {
            int i = cur[t];
            const double* ci = C + (size_t)i * n;
            double umin = BIG, usub = BIG; int jmin = 0;
