static void lapjv(const double* __restrict C, int n, int64_t* y_out) {
    const double BIG = 1e100;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> y(n, -1), x(n, -1);
    std::vector<int> free_rows(n);
    int nf = 0;

    for (int j = n - 1; j >= 0; --j) {
        const double* col0 = C + j;
        double mv = col0[0]; int mi = 0;
        for (int i = 1; i < n; ++i) {
            double val = C[(size_t)i * n + j];
            if (val < mv) { mv = val; mi = i; }
        }
        v[j] = mv;
        if (y[mi] < 0) { y[mi] = j; x[j] = mi; }
    }
    for (int i = 0; i < n; ++i) {
        int j = y[i];
        if (j < 0) { free_rows[nf++] = i; continue; }
        const double* ci = C + (size_t)i * n;
        double min1 = ci[j] - v[j], min2 = BIG;
        for (int k = 0; k < n; ++k) {
            if (k == j) continue;
            double red = ci[k] - v[k];
            if (red < min1) { min2 = min1; min1 = red; }
            else if (red < min2) min2 = red;
        }
        u[i] = min1;
        if (min1 < min2) v[j] -= (min2 - min1);
    }
    for (int pass = 0; pass < 2 && nf; ++pass) {
        int cnt = nf;
        std::vector<int> cur(free_rows.begin(), free_rows.begin() + cnt);
        nf = 0;
        for (int t = 0; t < cnt; ++t) {
            int i = cur[t];
            const double* ci = C + (size_t)i * n;
            double umin = BIG, usub = BIG; int jmin = 0;
            for (int j = 0; j < n; ++j) {
                double red = ci[j] - v[j];
                if (red < umin) { usub = umin; umin = red; jmin = j; }
                else if (red < usub) usub = red;
            }
            u[i] = umin;
            if (umin < usub) v[jmin] -= (usub - umin);
            int prev = x[jmin];
            if (prev >= 0) { y[prev] = -1; free_rows[nf++] = prev; }
            y[i] = jmin; x[jmin] = i;
        }
    }

    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n);
    // list of columns still unscanned, for the min-finding scan
    std::vector<int> cols(n);

    for (int t = 0; t < nf; ++t) {
        int fr = free_rows[t];
        const double* cfr = C + (size_t)fr * n;
        double ufr = u[fr];
        for (int j = 0; j < n; ++j) {
            dist[j] = cfr[j] - v[j] - ufr;
            pred[j] = fr;
            scanned[j] = 0;
            cols[j] = j;
        }
        int nrem = n;
        double mind = BIG; int jpos = 0;
        for (int p = 0; p < nrem; ++p) { int j = cols[p]; if (dist[j] < mind) { mind = dist[j]; jpos = p; } }
        while (true) {
            int jmin = cols[jpos];
            cols[jpos] = cols[--nrem];
            scanned[jmin] = 1;
            int im = x[jmin];
            if (im < 0) {
                for (int j = 0; j < n; ++j) if (scanned[j]) {
